import pandas as pd
from datetime import timedelta


def run(inputs: dict) -> dict:
    target_snapshot = inputs["target_snapshot"]
    cdc_events = inputs["cdc_events"]
    watermark = inputs["watermark"]

    # Determine watermark high_ts
    if len(watermark) == 0:
        high_ts = pd.Timestamp.min
    else:
        high_ts = watermark["high_ts"].max()

    # Build initial state from target_snapshot
    state = {}
    for row in target_snapshot.itertuples(index=False):
        state[row.user_id] = {
            "email": row.email,
            "status": row.status,
            "status_ts": row.status_ts,
        }

    # Filter events strictly after watermark
    events = cdc_events[cdc_events["event_ts"] > high_ts].copy()

    # Sort globally by (event_ts, event_seq) to apply sequentially
    events = events.sort_values(by=["event_ts", "event_seq"], kind="mergesort")

    seven_days = timedelta(days=7)

    for ev in events.itertuples(index=False):
        uid = ev.user_id
        op = ev.op
        ts = ev.event_ts
        email = ev.email

        cur = state.get(uid)

        if op == "D":
            if cur is None:
                # New user being soft-deleted: no prior state, use event email
                state[uid] = {
                    "email": email,
                    "status": "DELETED",
                    "status_ts": ts,
                }
            else:
                # Preserve existing email, just update status/status_ts
                state[uid] = {
                    "email": cur["email"],
                    "status": "DELETED",
                    "status_ts": ts,
                }
        elif op == "U":
            if cur is None or cur["status"] == "ACTIVE":
                state[uid] = {
                    "email": email,
                    "status": "ACTIVE",
                    "status_ts": ts,
                }
            else:
                # cur status == 'DELETED'
                deletion_ts = cur["status_ts"]
                if ts > deletion_ts + seven_days:
                    state[uid] = {
                        "email": email,
                        "status": "ACTIVE",
                        "status_ts": ts,
                    }
                else:
                    # discard, sticky deletion window
                    pass
        else:
            # Unknown op, ignore
            pass

    # Build output DataFrame
    rows = []
    for uid, info in state.items():
        rows.append({
            "user_id": uid,
            "email": info["email"],
            "status": info["status"],
            "status_ts": info["status_ts"],
        })

    new_snapshot = pd.DataFrame(rows, columns=["user_id", "email", "status", "status_ts"])

    if len(new_snapshot) > 0:
        new_snapshot = new_snapshot.sort_values(by="user_id", kind="mergesort").reset_index(drop=True)
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])
    else:
        new_snapshot = pd.DataFrame(columns=["user_id", "email", "status", "status_ts"])
        new_snapshot["user_id"] = new_snapshot["user_id"].astype("int64")
        new_snapshot["status_ts"] = pd.to_datetime(new_snapshot["status_ts"])

    return {"new_snapshot": new_snapshot}
